// Local review prototype: device storage only, no production endpoints or tracking.
import{createMap,distance,plural}from'./map.js';
import{createExporter}from'./share.js';
import{KEY,newId,createStore,backup,parse,merge,MAX_BYTES}from'./storage.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const [airports,land]=await Promise.all([fetch('/assets/airports.json').then(r=>r.json()),fetch('/assets/land.json').then(r=>r.json())]);
const model=createMap(airports,land),airport=model.airport;
const norm=s=>s.toLocaleLowerCase().replaceAll('ё','е').trim();
const search=airports.map(a=>({a,q:norm(`${a.city} ${a.code} ${a.name}`)}));
let exporterPromise;
const demo=[['SVX','IST','2025-09-14','TK 476'],['IST','CDG','2025-09-18','TK 1823'],['CDG','IST','2026-02-21','TK 1828'],['IST','SVX','2026-02-22','TK 475'],['SVX','DXB','2026-09-03','FZ 980'],['DXB','BKK','2026-09-04','EK 372']].map((f,id)=>({id:'demo_'+id,from:f[0],to:f[1],date:f[2],number:f[3]}));
let flights=[],personal=[],isDemo=false,period='',selected=null,editing=null,choice={from:null,to:null},box=null,fullBox=null;
let shareKind='map',shareFormat='story',shareLight=false,shareCard=null,shareBlob=null,shareRevision=0,previewURL=null;
let store,storageError='',pendingRestore=null,restoreRevision=0;
try{store=createStore(localStorage,new Set(airports.map(a=>a.code)));flights=personal=store.read();}catch(e){storageError='Не удалось прочитать сохранение. Оно не перезаписано. '+e.message;}
if(new URLSearchParams(location.search).has('demo')){flights=structuredClone(demo);isDemo=true;}
document.documentElement.dataset.theme=matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('ru-RU');
function km(f){return distance(airport[f.from],airport[f.to]);}
function visible(){return flights.filter(f=>!period||f.date?.startsWith(period));}
function totals(){let f=visible(),codes=[...new Set(f.flatMap(x=>[x.from,x.to]))];return {flights:f.length,countries:new Set(codes.map(c=>airport[c].country)).size,km:f.reduce((n,f)=>n+km(f),0),codes};}
function fit(){box=model.fit(visible(),$('#mapWrap').clientWidth/$('#mapWrap').clientHeight);}
function map(){const svg=$('#map');svg.setAttribute('viewBox',`${box.x} ${box.y} ${box.w} ${box.h}`);svg.innerHTML=model.body(visible(),box,$('#mapWrap').clientWidth,selected);bindRoutes(svg);$('.map-empty').hidden=visible().length>0;renderSelection($('#mapSelection'));if($('#fullMapDialog').open)drawFull();}
function bindRoutes(svg){svg.querySelectorAll('[data-route]').forEach(p=>p.onclick=()=>{selected=p.dataset.route;render(false);});}
function renderSelection(el){const f=visible().find(x=>x.id===selected);el.hidden=!f;if(!f){el.innerHTML='';return;}el.innerHTML=`<div><strong>${esc(airport[f.from].city)} → ${esc(airport[f.to].city)}</strong><small>≈ ${fmt(km(f))} км между аэропортами</small></div><button class="icon" aria-label="Поделиться этим перелётом" data-route-share>↗</button><button class="icon" aria-label="Снять выделение" data-unselect>×</button>`;el.querySelector('[data-unselect]').onclick=()=>{selected=null;render(false);};el.querySelector('[data-route-share]').onclick=()=>{if($('#fullMapDialog').open){close($('#fullMapDialog'),()=>makeShare('flight'));return;}makeShare('flight');};}
function drawFull(){const fs=visible(),wrap=$('#fullMapCanvas');if(!fullBox)fullBox=model.fit(fs,wrap.clientWidth/wrap.clientHeight);wrap.innerHTML=`<svg viewBox="${fullBox.x} ${fullBox.y} ${fullBox.w} ${fullBox.h}" aria-label="Карта маршрутов">${model.body(fs,fullBox,wrap.clientWidth,selected)}</svg>`;bindRoutes(wrap);renderSelection($('#fullMapSelection'));}
function render(reset=true){$('#storageStatus').textContent=storageError||(isDemo?'Пример не сохраняется. Ваши перелёты хранятся отдельно.':'Сохранено на этом устройстве · '+personal.length+' '+plural(personal.length,['перелёт','перелёта','перелётов']));$('#storageStatus').classList.toggle('storage-error',!!storageError);let t=totals();$('.atlas').classList.toggle('is-empty',t.flights===0);if(reset||!box)fit();map();$('#stats').innerHTML=`<div class="stat"><b>${t.flights}</b><span>${plural(t.flights,['перелёт','перелёта','перелётов'])}</span></div><div class="stat"><b>${t.countries}</b><span>${plural(t.countries,['страна','страны','стран'])} на карте</span></div><div class="stat"><b>${fmt(t.km)}</b><span>км по прямой ≈</span></div>`;
 $('#journalCount').textContent=period||'Все годы';
 const years=[...new Set(flights.map(f=>f.date?.slice(0,4)).filter(Boolean))].sort().reverse();$('#period').innerHTML='<option value="">За всё время</option>'+years.map(y=>`<option value="${y}">${y}</option>`).join('');$('#period').value=period;
 $('#shareNudge').hidden=flights.length===0;$$('[data-action="share"]').forEach(b=>b.disabled=!flights.length);
 $('.demo-bar').querySelector('span').textContent=isDemo?'Демонстрационная карта':'Локальная карта · без регистрации';$('#clearDemo').textContent=isDemo?'Вернуться к своей':'Посмотреть пример';
 $('#flightList').innerHTML=visible().slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(f=>`<article class="flight${selected===f.id?' selected':''}" tabindex="0" role="button" aria-label="${esc(airport[f.from].city+' — '+airport[f.to].city)}" data-id="${f.id}"><div class="flight-top"><span>${f.date?new Date(f.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}):'Дата не указана'}${f.number?' · '+esc(f.number):''}</span><button aria-label="Изменить перелёт ${esc(f.from+' — '+f.to)}" data-edit="${f.id}">···</button></div><div class="route"><div><strong>${f.from}</strong><small>${esc(airport[f.from].city)}</small></div><div class="route-line"><span>✈</span></div><div><strong>${f.to}</strong><small>${esc(airport[f.to].city)}</small></div></div></article>`).join('')||'<div class="empty-list">Перелётов пока нет.</div>';
 $('#flightList').querySelectorAll('[data-id]').forEach(el=>{const choose=()=>{selected=el.dataset.id;render(false);$('.atlas').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});};el.onclick=e=>{if(!e.target.closest('[data-edit]'))choose();};el.onkeydown=e=>{if(e.key==='Enter'&&!e.target.closest('[data-edit]'))choose();};});
 $$('[data-edit]').forEach(el=>el.onclick=()=>openForm(el.dataset.edit));
}
let toastTimer;function toast(s){$('#toast').onclick=null;$('#toast').style.pointerEvents='none';$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
// A local history entry lets Android/browser Back close a sheet instead of
// leaving the map. Closing by Escape/cross removes the same entry exactly once.
let afterClose=null;
function close(d,next=null){afterClose=next;d.close();}
function open(d){history.pushState({abDialog:d.id},'',location.href);d.dataset.history='1';d.showModal();document.body.style.overflow='hidden';}
window.addEventListener('popstate',()=>{for(const d of $$('dialog[open]')){delete d.dataset.history;d.close();}const next=afterClose;afterClose=null;next?.();});
$$('dialog .close').forEach(b=>b.onclick=()=>close(b.closest('dialog')));
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{document.body.style.overflow='';syncStored();if(d.dataset.history&&history.state?.abDialog===d.id){delete d.dataset.history;history.back();}});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close(d);}});});
const today=new Date(),todayString=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');$('#date').max=todayString;
function openForm(id=null){editing=id;$('#flightForm').reset();$('.extra-fields').open=id!==null;$('#formError').textContent='';$$('.suggestions').forEach(e=>e.innerHTML='');let f=flights.find(f=>f.id===id);choice={from:f?.from||null,to:f?.to||null};for(const side of ['from','to']){let a=airport[choice[side]];$('#'+side).value=a?`${a.city} · ${a.code}`:'';$('#'+side).setAttribute('aria-expanded','false');}
 $('#date').value=f?.date||'';$('#number').value=f?.number||'';$('#formTitle').textContent=f?'Ваш перелёт':'Добавить перелёт';$('#flightForm .save').textContent=f?'Сохранить изменения':'Добавить перелёт';$('#deleteFlight')?.remove();if(f){let b=document.createElement('button');b.id='deleteFlight';b.type='button';b.textContent='Удалить перелёт';b.style='background:none;color:#ff837a;width:100%;padding:15px;margin-top:5px';b.onclick=()=>{let saved=f;if(!applyFlights(flights.filter(x=>x.id!==f.id)))return;const deletedDemo=isDemo;close($('#addDialog'));render();toast('Перелёт удалён · можно отменить');$('#toast').style.pointerEvents='auto';$('#toast').onclick=()=>{if(isDemo!==deletedDemo)return;if(!applyFlights([...flights,saved]))return;render();toast('Перелёт восстановлен');$('#toast').onclick=null;$('#toast').style.pointerEvents='none';};};$('#flightForm').append(b);}open($('#addDialog'));if(!f)$('#from').focus();}
for(const side of ['from','to']){let input=$('#'+side),list=$('#'+side+'Results');const show=()=>{let q=norm(input.value);let rows=q?search.filter(x=>x.q.includes(q)).sort((a,b)=>(b.a.code.toLowerCase()===q)-(a.a.code.toLowerCase()===q)).slice(0,6).map(x=>x.a):['SVX','SVO','AYT','IST'].map(c=>airport[c]).filter(Boolean);list.innerHTML=rows.map(a=>`<button type="button" role="option" aria-selected="false" data-code="${a.code}"><span>${esc(a.city)}<small>${esc(a.name)}</small></span><b>${a.code}</b></button>`).join('')||'<p style="padding:12px">Не нашли аэропорт. Попробуйте название или IATA-код.</p>';input.setAttribute('aria-expanded','true');list.querySelectorAll('button').forEach((b,i)=>{b.onkeydown=e=>{const bs=[...list.querySelectorAll('button')];if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();bs[(i+(e.key==='ArrowDown'?1:bs.length-1))%bs.length].focus();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();input.focus();list.innerHTML='';input.setAttribute('aria-expanded','false');}};b.onclick=()=>{choice[side]=b.dataset.code;let a=airport[choice[side]];input.value=`${a.city} · ${a.code}`;list.innerHTML='';input.setAttribute('aria-expanded','false');if(side==='from')$('#to').focus();else input.focus();};});};input.oninput=()=>{choice[side]=null;show();};input.onfocus=()=>{if(!choice[side])show();};input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();list.querySelector('button')?.focus();}if(e.key==='Escape'&&list.childElementCount){e.preventDefault();e.stopPropagation();list.innerHTML='';input.setAttribute('aria-expanded','false');}};}
$('.swap').onclick=()=>{[choice.from,choice.to]=[choice.to,choice.from];let a=$('#from').value;$('#from').value=$('#to').value;$('#to').value=a;$$('.suggestions').forEach(e=>e.innerHTML='');};
$('#flightForm').onsubmit=e=>{e.preventDefault();if($('#date').value>todayString){$('#formError').textContent='Это история совершённых перелётов. Выберите прошедшую дату.';return;}if(!choice.from||!choice.to){$('#formError').textContent='Выберите оба аэропорта из подсказок.';return;}if(choice.from===choice.to){$('#formError').textContent='Аэропорты вылета и прилёта должны отличаться.';return;}let f={id:editing??(isDemo?'demo_'+newId():newId()),from:choice.from,to:choice.to,date:$('#date').value,number:$('#number').value.trim()};if(!applyFlights(editing===null?[...flights,f]:flights.map(x=>x.id===editing?f:x)))return;period='';selected=f.id;close($('#addDialog'));render();toast(editing===null?'Перелёт добавлен на вашу карту':'Изменения сохранены');};
$('#clearDemo').onclick=()=>{syncStored();if(isDemo){flights=personal;isDemo=false;}else{personal=flights;flights=structuredClone(demo);isDemo=true;}selected=null;period='';const url=new URL(location.href);if(isDemo)url.searchParams.set('demo','');else url.searchParams.delete('demo');history.replaceState(history.state,'',url);render();};
$('#period').onchange=()=>{period=$('#period').value;selected=null;fullBox=null;render();};
$('#fit').onclick=()=>{fit();map();};for(const [id,f] of [['zoomIn',.8],['zoomOut',1.25]])$('#'+id).onclick=()=>{if(box.w*f<50||box.w*f>1100)return;box={...box,x:box.x+box.w*(1-f)/2,y:box.y+box.h*(1-f)/2,w:box.w*f,h:box.h*f};map();};
// Backup belongs to the new journal. Never replace the site's existing
// settings or theme tile with a prototype-only control. Shared navigation is
// still a visual placeholder here, as are Search and Favourites.
$('#openBackup').onclick=()=>open($('#backupDialog'));
// Generate PNG before the share gesture: iOS must receive navigator.share
// directly from a tap, not after awaiting font loading or a long rasterisation.
async function refreshShare(){const rev=++shareRevision;shareBlob=null;$('#sharePreview').setAttribute('aria-busy','true');$('#nativeShare').disabled=true;$('#download').disabled=true;$('#shareStatus').textContent='Готовим изображение…';
 $$('.share-tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.shareKind===shareKind)));$$('[data-format]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.format===shareFormat)));
 $('#shareYear').hidden=shareKind!=='year';$('#shareFlight').hidden=shareKind!=='flight';$('#caption').hidden=true;
 try{exporterPromise??=createExporter(model);const exp=await exporterPromise;const card=exp.build({flights,kind:shareKind,year:$('#shareYear').value,flightId:$('#shareFlight').value,format:shareFormat,light:shareLight,demo:isDemo});if(rev!==shareRevision)return;
 shareCard=card;$('#caption').value=card.caption;const blob=await exp.png(card);if(rev!==shareRevision)return;shareBlob=blob;$('#sharePreview').setAttribute('aria-busy','false');if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(blob);$('#sharePreview').innerHTML=`<img src="${previewURL}" alt="Готовая карточка: ${shareKind==='flight'?'один перелёт':shareKind==='year'?'итоги года':'вся карта'}" width="${card.width}" height="${card.height}">`;$('#download').disabled=false;
 const file=new File([blob],'airportsboard-my-flights.png',{type:'image/png'}),can=!!navigator.canShare?.({files:[file]});$('#nativeShare').hidden=!can;$('#nativeShare').disabled=!can;$('#shareStatus').textContent=can?'Готово · выберите приложение после нажатия «Поделиться»':'Сохраните PNG и прикрепите в любимом приложении.';
 }catch(e){$('#sharePreview').setAttribute('aria-busy','false');$('#shareStatus').textContent='Не получилось создать PNG. Закройте окно и попробуйте снова.';}}
function makeShare(kind='map'){if(!flights.length){toast('Сначала добавьте перелёт');return;}shareKind=kind==='map'&&period?'year':kind;shareLight=document.documentElement.dataset.theme==='light';
 const years=[...new Set(flights.map(f=>f.date?.slice(0,4)).filter(Boolean))].sort().reverse();$('#shareYear').innerHTML=years.map(y=>`<option>${y}</option>`).join('');$('[data-share-kind="year"]').disabled=!years.length;if(period&&years.includes(period))$('#shareYear').value=period;
 $('#shareFlight').innerHTML=flights.map(f=>`<option value="${f.id}">${f.from} → ${f.to}${f.date?' · '+f.date:''}</option>`).join('');$('#shareFlight').value=selected??flights[flights.length-1].id;$('#sharePreview').innerHTML='';open($('#shareDialog'));refreshShare();}
$$('[data-share-kind]').forEach(b=>b.onclick=()=>{shareKind=b.dataset.shareKind;refreshShare();});$$('[data-format]').forEach(b=>b.onclick=()=>{shareFormat=b.dataset.format;refreshShare();});$('#shareYear').onchange=$('#shareFlight').onchange=refreshShare;$('#exportTheme').onclick=()=>{shareLight=!shareLight;refreshShare();};
$('#download').onclick=()=>{if(!shareBlob)return;const a=document.createElement('a'),u=URL.createObjectURL(shareBlob);a.href=u;a.download=`airportsboard-${shareKind}-${shareFormat}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);$('#shareStatus').textContent='PNG передан браузеру для сохранения.';};
$('#nativeShare').onclick=()=>{if(!shareBlob)return;navigator.share({files:[new File([shareBlob],'airportsboard-my-flights.png',{type:'image/png'})],title:'Мои перелёты'}).then(()=>{$('#shareStatus').textContent='Изображение передано выбранному приложению.';}).catch(e=>{if(e.name!=='AbortError')$('#shareStatus').textContent='Не удалось поделиться. Сохраните PNG.';});};
$('#copyCaption').onclick=async()=>{try{await Promise.race([navigator.clipboard.writeText(shareCard.caption),new Promise((_,reject)=>setTimeout(()=>reject(new Error('clipboard-timeout')),1500))]);$('#shareStatus').textContent='Подпись скопирована. Можно добавить к картинке.';}catch{$('#caption').hidden=false;$('#caption').select();$('#shareStatus').textContent='Выделите и скопируйте подпись ниже.';}};
$('#expandMap').onclick=()=>{if(!visible().length)return;fullBox=null;open($('#fullMapDialog'));drawFull();};
function zoomFull(f){if(!fullBox||fullBox.w*f<60||fullBox.w*f>1500)return;fullBox={...fullBox,x:fullBox.x+fullBox.w*(1-f)/2,y:fullBox.y+fullBox.h*(1-f)/2,w:fullBox.w*f,h:fullBox.h*f};drawFull();}
$('#fullZoomIn').onclick=()=>zoomFull(.8);$('#fullZoomOut').onclick=()=>zoomFull(1.25);$('#fullFit').onclick=()=>{fullBox=null;drawFull();};
let drag=null,moved=false;const full=$('#fullMapCanvas');full.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,box:{...fullBox}};moved=false;};full.onpointermove=e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>6)moved=true;if(!moved)return;full.setPointerCapture(e.pointerId);fullBox={...drag.box,x:drag.box.x-dx*drag.box.w/full.clientWidth,y:drag.box.y-dy*drag.box.h/full.clientHeight};drawFull();};full.onpointerup=full.onpointercancel=()=>{drag=null;};full.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);
$$('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();switch(b.dataset.action){case'add':openForm();break;case'share':makeShare('map');break;case'top':window.scrollTo({top:0,behavior:'smooth'});break;default:toast('В прототипе работает раздел «Перелёты»');}});

// Import preview and saving share the same validation path, so a corrupt backup
// cannot silently turn a complete journal into a partial one.
function applyFlights(next){try{if(isDemo){flights=next;return true;}if(!store)throw Error('Память браузера недоступна. Перелёт не сохранён.');personal=store.write(next);flights=personal;storageError='';return true;}catch(e){storageError=e.message;$('#formError').textContent=e.message;$('#restoreError').textContent=e.message;$('#storageStatus').textContent=e.message;toast(e.message);return false;}}
function syncStored(){if(!store)return;try{personal=store.read();if(!isDemo)flights=personal;storageError='';if(period&&!flights.some(f=>f.date.startsWith(period)))period='';render();}catch(e){storageError=e.message;$('#storageStatus').textContent=e.message;}}
window.addEventListener('storage',e=>{if(e.key!==KEY&&e.key!==null)return;if($('dialog[open]'))return;syncStored();});
function downloadText(text,name){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}
$('#backup').onclick=()=>{syncStored();if(storageError){try{const raw=localStorage.getItem(KEY);if(raw!==null)downloadText(raw,'airportsboard-unreadable-original.json');else toast(storageError);}catch{toast(storageError);}return;}downloadText(backup(personal),'airportsboard-backup-'+todayString+'.json');$('#backupStatus').textContent='Файл передан браузеру. Сохраните его в «Файлы» или на другом устройстве. Демопример в него не входит.';};
$('#restoreFile').onchange=async e=>{const revision=++restoreRevision,file=e.target.files?.[0];e.target.value='';if(!file)return;$('#backupStatus').textContent='Проверяем файл…';try{if(file.size>MAX_BYTES)throw Error('Файл слишком большой: максимум 2 МБ.');const text=await file.text();if(revision!==restoreRevision||!$('#backupDialog').open)return;const incoming=parse(text,new Set(airports.map(a=>a.code)));syncStored();if(storageError)throw Error(storageError);const result=merge(personal,incoming);pendingRestore=incoming;$('#restoreSummary').textContent=`Добавится: ${result.added}. Уже есть: ${result.existing}. Конфликтующих записей: ${result.conflicts}. Текущие записи сохранятся.`;$('#restoreError').textContent='';$('#restoreConfirm').disabled=!result.added;$('#restoreList').innerHTML=incoming.slice(0,5).map(f=>`<li>${esc(airport[f.from].city)} → ${esc(airport[f.to].city)} <small>${esc(f.date||'Без даты')}</small></li>`).join('');$('#backupStatus').textContent='';close($('#backupDialog'),()=>open($('#restoreDialog')));}catch(e){$('#backupStatus').textContent=e.message;}};
$('#restoreConfirm').onclick=()=>{if(!pendingRestore)return;try{const result=merge(personal,pendingRestore);if(!store)throw Error('Память браузера недоступна.');personal=store.write(result.flights);flights=personal;isDemo=false;period='';selected=null;pendingRestore=null;storageError='';close($('#restoreDialog'));render();toast('История восстановлена: добавлено '+result.added);}catch(e){$('#restoreError').textContent=e.message;}};

render();let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>render(),100);});
